pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize filling bins to specific "harmonic" fractions of capacity (e.g., 1/2, 1/3, 1/4).
    // The goal is to minimize post_residual while creating "fit-friendly" remainders for future items.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": remainders that are too small to fit typical items (e.g., < 15)
    // but too large to be considered "tight".
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Harmonic coupling: If post_residual is a multiple of ~25 (1/4 of capacity), it is mathematically 
    // better for packing items of size 25, 50, 75. 
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 3. Lookahead integration: If the next item can fit in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the post_residual after the NEXT item is near zero (perfect fit).
        let post_post = post_residual - next_item_size;
        if post_post < 5 {
            score -= 20.0;
        }
    }

    // 4. Threshold management: If this is the last fitting bin, penalize opening a new bin heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize space density over harmonic alignment.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. New bin heuristic: Only open a new bin if the current post_residual is "wasteful" (e.g., > 40)
    // and we have enough open bins already.
    if bin_residual == bin_capacity {
        if open_bins_count > 5 && post_residual > 40 {
            score = 5.0; // Low score to favor opening new bin
        } else {
            score = 100.0; // High score to discourage opening new bin unless necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps that are too small for common items (e.g., < 20), 
    // but reward filling bins tightly.
    // The "Best Fit" logic is embedded in the quadratic growth of the post_residual.
    let mut score = post * post * 0.01;

    // Lookahead logic: if the next item is large and the current post_residual is 
    // too small to accommodate it, we penalize this placement to keep that space 
    // available for a better fit or to trigger a new bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 0.5;
        }
    }

    // Encourage using existing bins when they are already "half-full" or more 
    // to keep the number of open bins (and thus the search space) low.
    // We penalize opening a new bin (where bin_residual == bin_capacity) 
    // increasingly as we progress through the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    } else {
        // If the bin is already open, favor it more if it aligns with the mean_residual
        // to keep bin fill levels homogeneous.
        score -= (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Balance Best-Fit (minimizing post_residual) with lookahead awareness
    // and a penalty for opening new bins unless the fit is truly abysmal.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: The post-residual (Best Fit principle)
    // We want post_residual to be as small as possible (close to 0).
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin
    // If it's a new bin, we apply a heavy penalty that decreases slightly as the stream progresses,
    // reflecting that we become more desperate for space towards the end.
    if is_new_bin {
        score += 45.0 * (1.0 - 0.5 * progress);
    }

    // 3. Lookahead Logic (k=2)
    // If we have a next item, we penalize residual space that is too small to fit it.
    // This is the "Dead Space" penalty.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a hole that cannot fit the next item.
            // The penalty is stronger if we have plenty of open bins.
            score += (next_item_size - post_residual) as f64 * (1.0 + open_bins_count as f64 * 0.1);
        } else {
            // Reward creating a bin that can actually fit the next item.
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // 4. Global State Calibration
    // If the mean residual is high, we are currently wasting space. 
    // We should be more aggressive in filling bins (lower score for tight fits).
    if mean_residual > 30.0 {
        score += (post_residual as f64) * 0.2;
    }

    // 5. Scarcity Constraint
    // If this is the only bin that can fit the item, we heavily prioritize it
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // 1. Base Score: Best Fit variant with a density-weighting factor.
    // Minimizing post_residual is standard, but we bias towards bins that are already 
    // "deep" to consolidate usage.
    let mut score = post * (1.0 + (bin_capacity - bin_residual) as f64 / bin_capacity as f64);

    // 2. Dead Zone Mitigation: Penalize residuals that are too small to hold common items 
    // (empirically < 12).
    if post > 0.0 && post < 12.0 {
        score += (12.0 - post) * 15.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // we reward this placement to keep "packing paths" open.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.2;
        } else {
            // Penalize if the current choice forces a new bin for the next item
            score += 5.0;
        }
    }

    // 4. Dynamic New-Bin Suppression: 
    // The cost of opening a new bin is non-linear relative to the stream progress.
    if bin_residual == bin_capacity {
        // Higher penalty for new bins as we reach the end of the stream
        let new_bin_cost = 45.0 + (progress * bin_capacity as f64 * 0.6);
        score += new_bin_cost;
    } else {
        // 5. Uniformity: Prevent 'orphaned' bins by pulling residuals toward the mean.
        // We use a lighter weight here to allow for some Best-Fit packing variance.
        let dev = (post - mean_residual).abs();
        score += dev * 0.25;
    }

    // 6. Criticality Override: 
    // If only one bin can accept this item, prioritize it heavily to avoid 
    // the high cost of a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 7. Open Bins Constraint: Slightly penalize high open bin counts to encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    score
}
